  f('particles','magnetic-force-size','洛伦兹磁力大小',t`F_B=\lvert q\rvert vB\sin\theta`,'受力运动',['F','q','v','B','theta'],'θ 为速度与磁场的夹角。','v 与 B 平行时磁力为零；求大小用 |q|，求方向仍用带符号 q。');
